//! Nginx Proxy Manager: the proxy hosts to add by hand.

use super::{Out, sites, tag};
use crate::proxy::{Plan, ProxySettings};

fn rpartition(s: &str) -> (&str, &str) {
    s.rsplit_once(':').unwrap_or(("", s))
}

pub(super) fn npm(on: &[&Plan], _s: &ProxySettings, lan: &[String]) -> Out {
    let mut l: Vec<String> = [
        "Nginx Proxy Manager: generated by wranglarr (wranglarr → Reverse proxy).",
        "",
        "Once: Access Lists → Add Access List, name it LAN only; under Access, allow:",
    ]
    .map(String::from)
    .to_vec();
    l.extend(lan.iter().map(|r| format!("    {r}")));
    l.push("  then deny all (the last rule), and save.".into());
    l.push(String::new());
    for (fqdn, ps) in sites(on) {
        l.push(format!("Hosts → Proxy Hosts → Add Proxy Host:  {fqdn}"));
        if let Some(root) = ps.iter().find(|p| p.path.is_empty()) {
            let (h, port) = rpartition(&root.up);
            l.extend([
                format!("    ({}, {})", root.name, tag(root)),
                format!("    Scheme http · Forward Hostname/IP {h} · Forward Port {port}"),
                "    Websockets Support: on · Block Common Exploits: on".into(),
                format!("    Access List: {}", if root.expose == "lan" { "LAN only" } else { "Publicly Accessible" }),
            ]);
            if root.sab {
                l.push("    Advanced → Custom Nginx Configuration:  proxy_set_header Host $proxy_host;".into());
            }
        }
        for p in &ps {
            if p.path.is_empty() {
                continue;
            }
            let (h, port) = rpartition(&p.up);
            let slash = if p.strip { "/" } else { "" };
            l.push(format!("    Custom locations → Add location {}{slash}  ({}, {})", p.path, p.name, tag(p)));
            l.push(format!("        Scheme http · Forward Hostname/IP {h}{slash} · Forward Port {port}"));
            if p.expose == "lan" {
                l.push(
                    "        (NPM's access lists are per host: put LAN-only apps on a host of their own, or use subdomains)"
                        .into(),
                );
            }
        }
        l.push("    SSL: Request a new SSL Certificate · Force SSL: on · HTTP/2: on".into());
        l.push(String::new());
    }
    (l.join("\n"), "npm-steps.txt", "Nginx Proxy Manager is set up in its web UI: follow these steps there.")
}
